/** OSA/ANSI j=(n(n+2)+m)/2, orthonormal over unit disk.
 * y points upward; negative m uses sin(|m| theta), positive m cos(m theta).
 * Coefficients are signed RMS amplitudes in waves at the current wavelength.
 */
export const MODES = [
  [0, 0, "Pistone", "P"],
  [1, -1, "Tilt Y", "TY"],
  [1, 1, "Tilt X", "TX"],
  [2, -2, "Astigmatismo 45°", "A45"],
  [2, 0, "Defocus", "D"],
  [2, 2, "Astigmatismo 0°", "A0"],
  [3, -3, "Trefoil Y", "T3Y"],
  [3, -1, "Coma verticale", "CY"],
  [3, 1, "Coma orizzontale", "CX"],
  [3, 3, "Trefoil X", "T3X"],
  [4, -4, "Tetrafoil Y", "T4Y"],
  [4, -2, "Astigmatismo secondario 45°", "A245"],
  [4, 0, "Sferica primaria", "S"],
  [4, 2, "Astigmatismo secondario 0°", "A20"],
  [4, 4, "Tetrafoil X", "T4X"],
].map(([n, m, name, short], j) => ({ n, m, name, short, j }));
export function basis(x, y, out = new Float64Array(15)) {
  const r = x * x + y * y,
    s6 = Math.sqrt(6),
    s8 = Math.sqrt(8),
    s10 = Math.sqrt(10);
  out[0] = 1;
  out[1] = 2 * y;
  out[2] = 2 * x;
  out[3] = s6 * 2 * x * y;
  out[4] = Math.sqrt(3) * (2 * r - 1);
  out[5] = s6 * (x * x - y * y);
  out[6] = s8 * (3 * x * x * y - y * y * y);
  out[7] = s8 * (3 * r - 2) * y;
  out[8] = s8 * (3 * r - 2) * x;
  out[9] = s8 * (x * x * x - 3 * x * y * y);
  out[10] = s10 * 4 * x * y * (x * x - y * y);
  out[11] = s10 * (4 * r - 3) * 2 * x * y;
  out[12] = Math.sqrt(5) * (6 * r * r - 6 * r + 1);
  out[13] = s10 * (4 * r - 3) * (x * x - y * y);
  out[14] = s10 * (x ** 4 - 6 * x * x * y * y + y ** 4);
  return out;
}
export function waveAt(c, x, y, b = new Float64Array(15)) {
  basis(x, y, b);
  let w = 0;
  for (let j = 0; j < 15; j++) w += c[j] * b[j];
  return w;
}
export function waveMap(coeff, size = 256) {
  const data = new Float32Array(size * size).fill(NaN),
    b = new Float64Array(15);
  let min = Infinity,
    max = -Infinity,
    sum = 0,
    sum2 = 0,
    count = 0;
  for (let row = 0; row < size; row++)
    for (let col = 0; col < size; col++) {
      const x = (2 * (col + 0.5)) / size - 1,
        y = 1 - (2 * (row + 0.5)) / size;
      if (x * x + y * y > 1) continue;
      const w = waveAt(coeff, x, y, b);
      data[row * size + col] = w;
      min = Math.min(min, w);
      max = Math.max(max, w);
      sum += w;
      sum2 += w * w;
      count++;
    }
  return {
    data,
    size,
    min,
    max,
    pv: max - min,
    mean: sum / count,
    rmsSampled: Math.sqrt(Math.max(0, sum2 / count - (sum / count) ** 2)),
    rms: Math.hypot(...coeff.slice(1)),
    hoa: Math.hypot(...coeff.slice(6)),
  };
}
export const initialState = () => ({
  coeff: [0, 0, 0, 0.08, 0.12, 0.12, 0, 0, 0.18, 0, 0, 0, 0.06, 0, 0],
  lambda: 550,
  diameter: 4,
  focal: 20,
  pitch: 1,
  resolution: 1024,
  boundary: "periodic",
  log: true,
  psfRange: 5,
  psfZoom: 16,
  psfX: 0,
  psfY: 0,
  target: "text",
  split: 50,
  comparisonMode: 8,
  comparisonAmplitude: 0.3,
  animationMode: 4,
  animationMax: 2,
  animationSeconds: 8,
  aoGain: 0.8,
  aoOrder: 14,
});
export function sampling(p) {
  const N = p.resolution * (p.boundary === "zero" ? 2 : 1),
    fno = p.focal / p.diameter;
  const airy = 1.2196698912665 * p.lambda * 0.001 * fno;
  const diameterPixels = (N * p.pitch) / (p.lambda * 0.001 * fno);
  return {
    N,
    fno,
    airy,
    diameterPixels,
    radius: diameterPixels / 2,
    cutoff: 1000 / (p.lambda * 0.001 * fno),
    nyquist: 500 / p.pitch,
    valid: fno >= 2.5 && diameterPixels <= N * 0.5 && diameterPixels >= 48,
  };
}
export function analyticMTF(nu) {
  if (nu < 0) nu = -nu;
  if (nu >= 1) return 0;
  return (2 / Math.PI) * (Math.acos(nu) - nu * Math.sqrt(1 - nu * nu));
}
export function fromPreset(name) {
  const c = Array(15).fill(0);
  if (name === "defocus" || name === "hyperopia") c[4] = 0.5;
  if (name === "myopia") c[4] = -0.5;
  if (name === "coma") c[8] = 0.3;
  if (name === "astigmatism") c[5] = 0.5;
  if (name === "combined") {
    c[4] = 0.5;
    c[8] = 0.3;
    c[5] = 0.8;
    c[12] = 0.15;
  }
  if (name === "keratoconus") {
    c[7] = -0.65;
    c[3] = 0.25;
    c[5] = 0.4;
    c[12] = 0.15;
  }
  return c;
}
/** Deterministic modal turbulence surrogate, not a spatial Kolmogorov screen. */
export function atmosphere(seed = 1, strength = 0.6) {
  let s = seed >>> 0;
  const rand = () => {
    s = (1664525 * s + 1013904223) >>> 0;
    return (s + 0.5) / 4294967296;
  };
  const c = Array(15).fill(0);
  for (let j = 1; j < 15; j++)
    c[j] =
      (Math.sqrt(-2 * Math.log(rand())) * Math.cos(2 * Math.PI * rand())) /
      (MODES[j].n + 1) ** 1.5;
  const norm = Math.hypot(...c);
  return c.map((v) => (v * strength) / norm);
}
export function corrected(c, gain, order) {
  return c.map((v, j) => (j > 0 && j <= order ? v * (1 - gain) : v));
}
export function validateSession(raw) {
  if (
    !raw ||
    raw.format !== "wavefront-studio" ||
    raw.version !== 1 ||
    !raw.state
  )
    throw Error("Formato sessione non riconosciuto.");
  const s = initialState(),
    p = raw.state;
  if (
    !Array.isArray(p.coeff) ||
    p.coeff.length !== 15 ||
    p.coeff.some((x) => !Number.isFinite(x) || Math.abs(x) > 3)
  )
    throw Error("Coefficienti non validi: occorrono 15 valori fra −3 e +3 λ.");
  s.coeff = p.coeff.slice();
  for (const [key, min, max] of [
    ["lambda", 380, 780],
    ["diameter", 1, 10],
    ["focal", 10, 100],
    ["pitch", 0.1, 4],
    ["split", 0, 100],
    ["psfRange", 2, 8],
    ["psfZoom", 1, 64],
    ["psfX", -1e5, 1e5],
    ["psfY", -1e5, 1e5],
    ["comparisonMode", 0, 14],
    ["comparisonAmplitude", -3, 3],
    ["animationMode", 0, 14],
    ["animationMax", 0.05, 3],
    ["animationSeconds", 2, 60],
    ["aoGain", 0, 1],
    ["aoOrder", 1, 14],
  ]) {
    if (p[key] !== undefined) {
      if (!Number.isFinite(p[key]) || p[key] < min || p[key] > max)
        throw Error("Parametro non valido: " + key);
      s[key] = p[key];
    }
  }
  for (const key of ["comparisonMode", "animationMode", "aoOrder"])
    if (!Number.isInteger(s[key])) throw Error("Indice modale non intero.");
  if (![512, 1024].includes(p.resolution))
    throw Error("Risoluzione non supportata.");
  s.resolution = p.resolution;
  if (!["periodic", "zero"].includes(p.boundary))
    throw Error("Condizione al bordo non valida.");
  s.boundary = p.boundary;
  if (typeof p.log === "boolean") s.log = p.log;
  if (
    [
      "text",
      "usaf",
      "siemens",
      "bars",
      "portrait",
      "landscape",
      "upload",
    ].includes(p.target)
  )
    s.target = p.target;
  if (
    raw.image !== null &&
    raw.image !== undefined &&
    (typeof raw.image !== "string" ||
      !raw.image.startsWith("data:image/png;base64,") ||
      raw.image.length > 24e6)
  )
    throw Error("Immagine sessione non valida.");
  return { state: s, image: raw.image || null };
}
