/** In-place radix-2 FFT; forward exp(-i2πkn/N), inverse normalized by N.
 * Cached twiddles and bit reversals are shared by rows and columns.
 */
const plans = new Map();
function plan(n) {
  if (plans.has(n)) return plans.get(n);
  if (n < 2 || n & (n - 1)) throw Error("La FFT richiede una potenza di due.");
  const rev = new Uint32Array(n),
    cos = new Float64Array(n / 2),
    sin = new Float64Array(n / 2);
  for (let i = 0; i < n; i++) {
    let a = i,
      r = 0;
    for (let k = 1; k < n; k <<= 1) {
      r = (r << 1) | (a & 1);
      a >>= 1;
    }
    rev[i] = r;
  }
  for (let i = 0; i < n / 2; i++) {
    cos[i] = Math.cos((2 * Math.PI * i) / n);
    sin[i] = Math.sin((2 * Math.PI * i) / n);
  }
  const p = { rev, cos, sin };
  plans.set(n, p);
  return p;
}
export function fft1(re, im, inverse = false) {
  const n = re.length,
    { rev, cos, sin } = plan(n);
  for (let i = 0; i < n; i++) {
    const j = rev[i];
    if (j > i) {
      let t = re[i];
      re[i] = re[j];
      re[j] = t;
      t = im[i];
      im[i] = im[j];
      im[j] = t;
    }
  }
  for (let width = 2; width <= n; width <<= 1) {
    const half = width / 2,
      step = n / width;
    for (let base = 0; base < n; base += width)
      for (let j = 0; j < half; j++) {
        const k = j * step,
          c = cos[k],
          s = (inverse ? 1 : -1) * sin[k],
          a = base + j,
          b = a + half;
        const tr = c * re[b] - s * im[b],
          ti = s * re[b] + c * im[b];
        re[b] = re[a] - tr;
        im[b] = im[a] - ti;
        re[a] += tr;
        im[a] += ti;
      }
  }
  if (inverse)
    for (let i = 0; i < n; i++) {
      re[i] /= n;
      im[i] /= n;
    }
}
export function fft2(re, im, n, inverse = false) {
  const a = new Float64Array(n),
    b = new Float64Array(n);
  for (let y = 0; y < n; y++) {
    const start = y * n;
    a.set(re.subarray(start, start + n));
    b.set(im.subarray(start, start + n));
    fft1(a, b, inverse);
    re.set(a, start);
    im.set(b, start);
  }
  for (let x = 0; x < n; x++) {
    for (let y = 0; y < n; y++) {
      a[y] = re[y * n + x];
      b[y] = im[y * n + x];
    }
    fft1(a, b, inverse);
    for (let y = 0; y < n; y++) {
      re[y * n + x] = a[y];
      im[y * n + x] = b[y];
    }
  }
  return { re, im };
}
export function multiply(ar, ai, br, bi) {
  const re = new Float64Array(ar.length),
    im = new Float64Array(ar.length);
  for (let i = 0; i < ar.length; i++) {
    re[i] = ar[i] * br[i] - ai[i] * bi[i];
    im[i] = ar[i] * bi[i] + ai[i] * br[i];
  }
  return { re, im };
}
